public class ByteVector {
    private byte[] data;
    private int length;

    public ByteVector(int initialCapacity) {
        this.data = new byte[initialCapacity];
        this.length = 0;
    }

    private void enlarge(int size) {
        int newCapacity = (data.length << 1) + size;
        data = Arrays.copyOf(data, newCapacity);
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteLength == 0) {
            return this;
        }

        int loc0 = this.length;
        if (loc0 + byteLength > data.length) {
            enlarge(byteLength);
        }

        if (byteArrayValue == null) {
            Arrays.fill(data, loc0, loc0 + byteLength, (byte) 0);
        } else {
            System.arraycopy(byteArrayValue, byteOffset, data, loc0, byteLength);
        }

        this.length = loc0 + byteLength;
        return this;
    }
}

