import java.util.Stack;

private void pop(final String descriptor) {
    Stack<String> outputFrameStack = new Stack<>();
    if (descriptor.contains("(")) {
        int start = descriptor.indexOf('(') + 1;
        int end = descriptor.indexOf(')');
        String arguments = descriptor.substring(start, end);
        while (!arguments.isEmpty()) {
            char type = arguments.charAt(0);
            if (type == 'L' || type == '[') {
                int semiColonIndex = arguments.indexOf(';');
                outputFrameStack.pop();
                arguments = arguments.substring(semiColonIndex + 1);
            } else {
                outputFrameStack.pop();
                arguments = arguments.substring(1);
            }
        }
    } else {
        char type = descriptor.charAt(0);
        if (type == 'L' || type == '[') {
            outputFrameStack.pop();
        } else {
            outputFrameStack.pop();
        }
    }
}

