protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<V> vertexList = new ArrayList<>();
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, vertexList, 0.0);
    }

    V startVertex = null;
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (startVertex == null) {
            startVertex = source;
        }
        vertexList.add(source);
        if (!tour.contains(graph.getEdge(target, source))) {
            vertexList.add(target);
        }
    }

    double weight = 0.0;
    for (E edge : tour) {
        weight += graph.getEdgeWeight(edge);
    }

    return new GraphPathImpl<>(graph, startVertex, vertexList, weight);
}

