                case 'I':
                case 'S':
                case 'Z':
                    outputFrameStack.pop();
                    index++;
                    break;
                case 'D':
                case 'J':
                    outputFrameStack.pop();
                    outputFrameStack.pop();
                    index++;
                    break;
                case 'L':
                    int semiColonIndex = arguments.indexOf(';', index);
                    outputFrameStack.pop();
                    index = semiColonIndex + 1;
                    break;
                case '[':
                    outputFrameStack.pop();
                    index++;
                    break;
                default:
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
        }
    } else {
        char c = descriptor.charAt(0);
        switch (c) {
            case 'B':
            case 'C':
            case 'F':
            case 'I':
            case 'S':
            case 'Z':
                outputFrameStack.pop();
